test('recordLogin sets last_login_at on the active user', (t, done) => {
  const before = Date.now();
  recordLogin('grace@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user.email, 'grace@example.com');
    const at = Date.parse(user.last_login_at);
    assert.ok(at >= before && at <= Date.now());
    done();
  });
});

test('recordLogin errors for a soft-deleted user', (t, done) => {
  recordLogin('alan@example.com', (err, user) => {
    assert.match(err.message, /no active user/);
    assert.equal(user, undefined);
    done();
  });
});
"""
open(p,'w').write(s)
