s=open(p).read()
s+="""
test('UserRepository.findActiveByEmail skips soft-deleted users', async () => {
  const repo = new UserRepository();
  assert.equal((await repo.findActiveByEmail('ada@example.com')).id, 1);
  assert.equal(await repo.findActiveByEmail('alan@example.com'), null);
});

test('UserRepository.setLastLogin stores the timestamp', async () => {
  const row = await new UserRepository().setLastLogin(1, '2026-10-22T00:00:00.000Z');
  assert.equal(row.last_login_at, '2026-10-22T00:00:00.000Z');
});
"""
